     1	const { BasePage } = require('./BasePage');
     2	
     3	class ListMenuPage extends BasePage {
     4	  constructor(page) {
     5	    super(page);
     6	    // getByRole('navigation', {name: ...}) is not usable here: the base
     7	    // SFCC list-menu component's aria-label is translated per locale
     8	    // ("Main navigation" in English, "Navigation principale" in French —
     9	    // confirmed against fr-eu), so an English-text match silently breaks
    10	    // on every non-English site. Its id ("list-menu") is the base
    11	    // component's own stable DOM anchor, independent of locale/translation.
    12	    // CSS selector, last resort per BasePage's selector-priority doc, used
    13	    // because no locale-independent ARIA/data-testid option exists.
    14	    this.nav = page.locator('#list-menu');
    15	  }
    16	
    17	  async goToSite(urlPrefix) {
    18	    return this.goto(urlPrefix ? `${urlPrefix}/` : '/');
    19	  }
    20	
    21	  // Desktop-only (#list-menu is hidden below the lg breakpoint) — see
    22	  // MobileDrawerMenuPage for the separate mobile entry point, which is a
    23	  // genuinely different component, not a responsive variant of this one.
    24	  //
    25	  // Only relative, path-based hrefs are in scope for a site-prefix check —
    26	  // filters out any external/anchor/protocol links a future nav item might
    27	  // add, rather than asserting on link types this test isn't about.
    28	  async getNavLinkHrefs() {
    29	    const links = this.nav.getByRole('link');
    30	    await links.first().waitFor({ state: 'visible' });
    31	    const hrefs = await links.evaluateAll((elements) => elements.map((el) => el.getAttribute('href')));
    32	    return hrefs.filter((href) => href && href.startsWith('/'));
    33	  }
    34	}
    35	
    36	module.exports = { ListMenuPage };

